call_board_init_f_0: mv a0, sp jal board_init_f_alloc_reserve
/* * Save global data pointer for later. We don't set it here because it * is not initialized yet. */ mv s0, a0
/* setup stack */ #if CONFIG_IS_ENABLED(SMP) /* tp: hart id */ slli t0, tp, CONFIG_STACK_SIZE_SHIFT sub sp, a0, t0 #else mv sp, a0 #endif
call_harts_early_init: jal harts_early_init
